package com.carepath.vision;
import static org.junit.jupiter.api.Assertions.*;
import com.carepath.intelligence.*;
import static com.carepath.intelligence.ExtractionData.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class VisionValidatorTest {
    private final VisionValidator validator=new VisionValidator();
    private Page page(String text){return new Page(1,text,Method.TESSERACT_OCR,.8,List.of(new Line(0,text.length(),.8,new Box(0,.1,1,.1))));}
    private String reading(String value){return "{\"readings\":[{\"testName\":\"Glucose\",\"value\":\""+value+"\",\"unit\":\"mg/dL\",\"referenceRange\":\"70-110\",\"date\":\"2026-07-18\",\"column\":\"Current\",\"box\":{\"x\":0,\"y\":0.1,\"width\":1,\"height\":0.1}}],\"unreadable\":false}";}
    @Test void disagreementDoesNotRepairDecimalOrConfirm(){var r=validator.validate(reading("26.2"),page("Glucose 262 mg/dL"),"fixture");assertEquals("26.2",r.readings().getFirst().reading().value());assertTrue(r.readings().getFirst().warnings().contains("OCR_DISAGREEMENT_OR_MISSING_EVIDENCE"));assertTrue(r.readings().getFirst().warnings().contains("SOURCE_REVIEW_REQUIRED"));}
    @Test void abnormalValueIsNotChangedToFitRange(){var r=validator.validate(reading("262"),page("Glucose 262 mg/dL"),"fixture");assertEquals("262",r.readings().getFirst().reading().value());assertFalse(r.readings().getFirst().warnings().contains("OCR_DISAGREEMENT_OR_MISSING_EVIDENCE"));assertTrue(r.readings().getFirst().warnings().contains("MODEL_OUTPUT_UNVERIFIED"));}
    @Test void numericSubstringDoesNotCountAsAgreement(){assertTrue(validator.validate(reading("26"),page("Glucose 262 mg/dL"),"fixture").readings().getFirst().warnings().contains("OCR_DISAGREEMENT_OR_MISSING_EVIDENCE"));}
    @Test void valueElsewhereOnPageDoesNotCorroborateRegion(){Page p=new Page(1,"Glucose 26.2 mg/dL",Method.TESSERACT_OCR,.9,List.of(new Line(0,17,.9,new Box(0,.8,1,.1))));assertTrue(validator.validate(reading("26.2"),p,"fixture").readings().getFirst().warnings().contains("OCR_DISAGREEMENT_OR_MISSING_EVIDENCE"));}
    @Test void unsupportedUnitIsFlagged(){assertTrue(validator.validate(reading("26.2").replace("mg/dL","mgid)"),page("Glucose 26.2 mgid)"),"fixture").readings().getFirst().warnings().contains("UNIT_UNSUPPORTED"));}
    @Test void malformedDateIsFlagged(){assertTrue(validator.validate(reading("26.2").replace("2026-07-18","2026-99-99"),page("Glucose 26.2 mg/dL"),"fixture").readings().getFirst().warnings().contains("INVALID_DATE"));}
    @Test void rejectsOutOfPageAndExtraFieldsAndTypeCoercion(){for(String s:List.of(reading("26.2").replace("\"width\":1","\"width\":2"),reading("26.2").replace("\"value\":\"26.2\"","\"value\":26.2"),reading("26.2").replace("\"unreadable\":false","\"unreadable\":false,\"confirmed\":true"),reading("26.2")+" {}"))assertThrows(RuntimeException.class,()->validator.validate(s,page("Glucose 26.2 mg/dL"),"fixture"));}
    @Test void keepsHistoricalColumnsSeparate(){String row=reading("93.1");String object=row.substring(row.indexOf('[')+1,row.lastIndexOf(']'));String two="{\"readings\":["+object+","+object.replace("93.1","102").replace("Current","Previous").replace("2026-07-18","2025-09-21")+"],\"unreadable\":false}";var result=validator.validate(two,page("Glucose 93.1 102 mg/dL"),"fixture");assertEquals(2,result.readings().size());assertEquals("2025-09-21",result.readings().get(1).reading().date());assertEquals("102",result.readings().get(1).reading().value());}
    @Test void cleanNativePageDoesNotEscalateButScannedPageDoes(){var nativePage=TextPages.nativePage(1,"LAB REPORT\nLaboratory: Synthetic Lab\nReport date: 2026-07-18\nTest | Result | Unit | Reference | Flag\nGlucose | 92.4 | mg/dL | 70 - 140 | NORMAL\n");var pipeline=new ExtractionPipeline(null);var clean=pipeline.parse(List.of(nativePage));assertTrue(new VisionRouting().pages(clean).isEmpty(),clean.toString());var scanned=pipeline.parse(List.of(new Page(1,nativePage.text(),Method.TESSERACT_OCR,.8,nativePage.lines())));assertEquals(1,new VisionRouting().pages(scanned).size());}
    @Test void disabledProviderAndExplicitConfiguration(){var p=new OpenAiVisionProvider(false,true,"synthetic-key","synthetic-model",new com.fasterxml.jackson.databind.ObjectMapper());assertFalse(p.available());assertThrows(RuntimeException.class,()->p.read(new byte[]{1},"image/png"));assertFalse(new OpenAiVisionProvider(true,false,"synthetic-key","synthetic-model",new com.fasterxml.jackson.databind.ObjectMapper()).available());assertEquals(false,p.body(new byte[]{1},"image/png").get("store"));assertThrows(RuntimeException.class,()->p.body(new byte[6000001],"image/png"));}
    @Test void boundedResponseCancelsWhenTooLarge(){var body=new OpenAiVisionProvider.LimitedBody(2);boolean[] cancelled={false};body.onSubscribe(new java.util.concurrent.Flow.Subscription(){public void request(long n){}public void cancel(){cancelled[0]=true;}});body.onNext(List.of(java.nio.ByteBuffer.wrap(new byte[3])));assertTrue(cancelled[0]);assertTrue(body.result.isCompletedExceptionally());}
}
